ve e Missão","/chave/m2/a05-ficha.html"]]},{"t":"Aula 6 · Verbos que mudam: quiero, puedo, pido","i":[["video","Vídeo · Verbos que mudam: quiero, puedo, pido",null],["html","Exercícios (12)","/chave/m2/a06-exercicios.html"],["html","Ficha, Banco Chave e Missão","/chave/m2/a06-ficha.html"]]},{"t":"Aprender a Aprender · Revisar sem começar do zero","i":[["video","Vídeo · Revisão espaçada e ativa",null],["html","Revisar sem começar do zero","/chave/m2/aprender-a-aprender.html"]]},{"t":"Aula 7 · Ir, hacer, tener: os três que mais aparecem","i":[["video","Vídeo · Ir, hacer, tener: os três que mais aparecem",null],["html","Exercícios (12)","/chave/m2/a07-exercicios.html"],["html","Ficha, Banco Chave e Missão","/chave/m2/a07-ficha.html"]]},{"t":"Aula 8 · Me gusta, me encanta: gostos sem traduzir","i":[["video","Vídeo · Me gusta, me encanta: gostos sem traduzir",null],["html","Exercícios (12)","/chave/m2/a08-exercicios.html"],["html","Ficha, Banco Chave e Missão","/chave/m2/a08-ficha.html"]]},{"t":"Aula 9 · Família e pessoas próximas: mi, tu, su","i":[["video","Vídeo · Família e pessoas próximas: mi, tu, su",null],["html","Exercícios (12)","/chave/m2/a09-exercicios.html"],["html","Ficha, Banco Chave e Missão","/chave/m2/a09-ficha.html"]]},{"t":"Aula 10 · Muy ou mucho? E como devolver a pergunta","i":[["video","Vídeo · Muy ou mucho? E como devolver a pergunta",null],["html","Exercícios (12)","/chave/m2/a10-exercicios.html"],["html","Ficha, Banco Chave e Missão","/chave/m2/a10-ficha.html"]]},{"t":"Imersão Cultural · México","i":[["html","Expressões mexicanas (8)","/chave/m2/imersao.html"]]},{"t":"Revisão Inteligente","i":[["video","Vídeo · O boletim publicado",null],["html","O boletim e o semáforo","/chave/m2/revisao-boletim.html"],["html","Quiz do módulo (12)","/chave/m2/revisao-quiz.html"]]},{"t":"Checkpoint · Minha semana em espanhol","i":[["html","Checkpoint: as perguntas da Valeria","/chave/m2/checkpoint.html"]]}]}]'::jsonb;
  prog uuid;
  m jsonb; f jsonb; it jsonb;
  mid uuid; fid uuid; matid uuid;
  om int := 0; ofa int; oi int;
begin
  insert into turmas(nome, idioma, descricao, ordem)
  values ('Espanhol Chave', 'espanhol', 'Formação do zero ao B2 em três etapas: Base, Ampliação e Aprofundamento.', 5)
  returning id into prog;
  insert into turma_membros(turma_id, aluno_id) values (prog, '439e6c42-60de-433c-8de0-d1458eaf12ec');
  for m in select * from jsonb_array_elements(dados) loop
    om := om + 1;
    insert into materias(titulo, descricao, categoria, ordem, capa_path)
    values (m->>'t', m->>'d', 'trilha', 100 + om, m->>'c') returning id into mid;
    insert into programa_materias(turma_id, materia_id, ordem) values (prog, mid, om);
    ofa := 0; oi := 0;
    for f in select * from jsonb_array_elements(m->'f') loop
      insert into fases(materia_id, titulo, ordem) values (mid, f->>'t', ofa) returning id into fid;
      ofa := ofa + 1;
      for it in select * from jsonb_array_elements(f->'i') loop
        oi := oi + 1;
        insert into materiais(materia_id, fase_id, tipo, titulo, url, ordem, idioma, visivel_todos)
        values (mid, fid, it->>0, it->>1, it->>2, oi, 'espanhol', false) returning id into matid;
        insert into material_turmas(material_id, turma_id) values (matid, prog);
      end loop;
    end loop;
  end loop;
end $$;
